     suspend fun resumeCampaign(campaignId: String): ResumeCampaignResult {
         val result = supabase.postgrest.rpc(
             "resume_campaign",
             ResumeCampaignParams(campaignId = campaignId)
         ).decodeAs<ResumeCampaignResult>()
