             } catch (e: Exception) {
                 previous?.file?.delete()
                 _uiState.update {
                     it.copy(
                         preparedScreenshot = null,
                         selectedScreenshotUri = null,
                         isPreparingScreenshot = false,
                         error = friendlyError(e, localizer),
                     )
