             }
             return null
         }

         // Nếu có nhiều directive max-age (duplicate/conflicting) -> fail-closed
         if (maxAgeDirectives.size > 1) {
             return 0L
         }

         val directive = maxAgeDirectives.first()
         if (!directive.contains('=')) {
