 CREATE OR REPLACE FUNCTION public.verify_media_access_grant_internal(
     p_report_id uuid,
     p_user_id uuid,
     p_grant_token text,
-    p_variant text DEFAULT 'full'::text,
-    p_expires_at_epoch bigint DEFAULT NULL::bigint,
